import re
from collections import Counter
p="The_Method_1_6-2.md"
L=open(p,encoding="utf-8").read().split("\n")
BODY=range(11208,11498)   # 1-based body span
def zone(i): return "BODY" if i in BODY else ("CONTENTS" if i<200 else "PROSE")
sec=Counter(); byname=Counter(); bare=Counter(); eg=Counter()
sites={}
for i,l in enumerate(L,1):
    z=zone(i)
    for m in re.findall(r"§\s?F\.\d+(?:\.\d+)?", l):
        sec[(z,m.replace(" ",""))]+=1
        if z!="BODY": sites.setdefault(m.replace(" ",""),[]).append(i)
    if re.search(r"Appendix\s+F\b", l): byname[z]+=1
    for m in re.findall(r"(?<![§.\w])F\.\d+\.\d+", l):
        bare[(z,m)]+=1
    if "E(G)" in l: eg[z]+=1
print("--- §F.n.n by zone ---")
for k in sorted(sec): print("  ",k,sec[k])
print("--- 'Appendix F' by name ---", dict(byname))
print("--- bare F.n.n ---")
for k in sorted(bare): print("  ",k,bare[k])
print("--- E(G) ---", dict(eg))
print("--- non-body §F sites ---")
for k in sorted(sites): print("  ",k,sites[k])
EOF

